#define main archived_dp_main
#include "../dp-cuda/main.cu"
#undef main
#include <fstream>
#include <string>
#include <dlfcn.h>
struct Case{int n,pad,type;void*a,*b,*d;double expected;};
int main(int argc,char**argv){int mode=argc>1?atoi(argv[1]):1;std::vector<Case>cs;std::vector<double>prefix;for(int type=0;type<2;type++){std::ifstream f("study_inputs_i32.bin",std::ios::binary);for(int z=0;z<2;z++){int32_t n,pad;f.read((char*)&n,4);f.read((char*)&pad,4);std::vector<int32_t>ai(pad),bi(pad);f.read((char*)ai.data(),pad*4);f.read((char*)bi.data(),pad*4);if(!f)return 3;Case c;c.n=n;c.pad=pad;c.type=type;c.expected=0;int64_t abssum=0;for(int i=0;i<n;i++){int64_t prod=int64_t(ai[i])*bi[i];c.expected+=prod;abssum+=llabs(prod);}if(abssum>=(1<<24))return 4;int bytes=type?8:4;GPU_CHECK(cudaMalloc(&c.a,pad*bytes));GPU_CHECK(cudaMalloc(&c.b,pad*bytes));GPU_CHECK(cudaMalloc(&c.d,bytes));prefix.push_back(n);prefix.push_back(pad);if(type){std::vector<double>a(ai.begin(),ai.end()),b(bi.begin(),bi.end());GPU_CHECK(cudaMemcpy(c.a,a.data(),pad*8,cudaMemcpyHostToDevice));GPU_CHECK(cudaMemcpy(c.b,b.data(),pad*8,cudaMemcpyHostToDevice));GPU_CHECK(cudaMemcpy(a.data(),c.a,pad*8,cudaMemcpyDeviceToHost));GPU_CHECK(cudaMemcpy(b.data(),c.b,pad*8,cudaMemcpyDeviceToHost));prefix.insert(prefix.end(),a.begin(),a.end());prefix.insert(prefix.end(),b.begin(),b.end());}else{std::vector<float>a(ai.begin(),ai.end()),b(bi.begin(),bi.end());GPU_CHECK(cudaMemcpy(c.a,a.data(),pad*4,cudaMemcpyHostToDevice));GPU_CHECK(cudaMemcpy(c.b,b.data(),pad*4,cudaMemcpyHostToDevice));GPU_CHECK(cudaMemcpy(a.data(),c.a,pad*4,cudaMemcpyDeviceToHost));GPU_CHECK(cudaMemcpy(b.data(),c.b,pad*4,cudaMemcpyDeviceToHost));prefix.insert(prefix.end(),a.begin(),a.end());prefix.insert(prefix.end(),b.begin(),b.end());}cs.push_back(c);}}
cublasHandle_t handle;BLAS_CHECK(cublasCreate(&handle));BLAS_CHECK(cublasSetPointerMode(handle,CUBLAS_POINTER_MODE_DEVICE));int version;BLAS_CHECK(cublasGetVersion(handle,&version));Dl_info li;dladdr((void*)cublasDotEx,&li);printf("VENDOR_CUBLAS %s %d\n",li.dli_fname,version);std::vector<double>host(4);auto launch=[&](int i){auto&c=cs[i];int bytes=c.type?8:4;if(mode==1){GPU_CHECK(cudaMemset(c.d,0,bytes));if(c.type)dot_product<double><<<c.pad/(1024*4),1024>>>((double*)c.a,(double*)c.b,(double*)c.d,c.pad/4);else dot_product<float><<<c.pad/(1024*4),1024>>>((float*)c.a,(float*)c.b,(float*)c.d,c.pad/4);}else if(mode==2){auto t=c.type?CUDA_R_64F:CUDA_R_32F;BLAS_CHECK(cublasDotEx(handle,c.n,c.a,t,1,c.b,t,1,c.d,t,t));}else{if(c.type)host[i]=std::transform_reduce(std::execution::par_unseq,(double*)c.a,(double*)c.a+c.n,(double*)c.b,double(0));else host[i]=std::transform_reduce(std::execution::par_unseq,(float*)c.a,(float*)c.a+c.n,(float*)c.b,float(0));}};
for(int i=0;i<4;i++)for(int r=0;r<100;r++)launch(i);GPU_CHECK(cudaDeviceSynchronize());bool all=true;for(int trial=1;trial<=5;trial++){std::vector<double>ts;for(int i=0;i<4;i++){GPU_CHECK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int r=0;r<20;r++)launch(i);GPU_CHECK(cudaGetLastError());GPU_CHECK(cudaDeviceSynchronize());ts.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/20);}auto out=prefix;bool ok=true;double err=0;for(int i=0;i<4;i++){double value;if(mode==3)value=host[i];else if(cs[i].type)GPU_CHECK(cudaMemcpy(&value,cs[i].d,8,cudaMemcpyDeviceToHost));else{float v;GPU_CHECK(cudaMemcpy(&v,cs[i].d,4,cudaMemcpyDeviceToHost));value=v;}out.push_back(value);err=fmax(err,fabs(value-cs[i].expected));ok&=std::isfinite(value)&&value==cs[i].expected;}all&=ok;std::string file=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/dp_trial"+std::to_string(trial)+".bin";FILE*f=fopen(file.c_str(),"wb");if(!f)return 5;fwrite(out.data(),8,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"component_seconds\":[%.12g,%.12g,%.12g,%.12g],\"correct\":%s,\"checked_values\":4,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"internal_repeats\":20,\"jit_excluded\":true,\"timing_region\":\"four_FP32_FP64_named_dot_cases_meanloop_sum\",\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,ts[0]+ts[1]+ts[2]+ts[3],ts[0],ts[1],ts[2],ts[3],ok?"true":"false",err,err,file.c_str(),out.size());}for(auto&c:cs){GPU_CHECK(cudaFree(c.a));GPU_CHECK(cudaFree(c.b));GPU_CHECK(cudaFree(c.d));}BLAS_CHECK(cublasDestroy(handle));puts(all?"PASS":"FAIL");return all?0:1;}
